def sort_age(lst):
    if lst==[]:
        return []
    new_lst=[lst[0],]
    for x in lst[1:]:
        if x[1] > new_lst[-1][1]:
            new_lst += [x,]
        else:
            count=0
            while count<len(new_lst):
                if x[1] > new_lst[count][1]:
                    count+=1
                    continue
                else:
                    new_lst = new_lst[0:count]+[x,]+new_lst[count:]
                    break
    return new_lst[::-1]

def sort_age(lst):
	current = []
	tup = ()
	for i in lst:
		current.append(list(i))
	sort = []
	while current:
		largest = current[0]
		for element in current:
			if element[1] > largest[1]:
				largest = element
		current.remove(largest)
		sort.append(largest)
	for i in sort:
		tup += ((i[0],i[1]),)
	return list(tup)
